"use client";
import { motion, useReducedMotion } from "framer-motion";
import { AlertCircle, ArrowUpRight, Check, Loader2, Mail, MapPin, Send, ShieldCheck } from "lucide-react";
import { useMemo, useState } from "react";
import { contact } from "@/data/miror-v4-content";

type FormState="idle"|"submitting"|"success"|"error";
interface Model{name:string;company:string;email:string;phone:string;type:string;location:string;message:string;consent:boolean;website:string;}
const initial:Model={name:"",company:"",email:"",phone:"",type:"",location:"",message:"",consent:false,website:""};
const types=["Infrastructure / civil works","Irrigation / canal works","Residential construction","Structural / RCC works","Aluminium formwork","Other"];
const field="w-full rounded-xl border border-black/12 bg-white/15 px-4 py-3.5 text-sm outline-none placeholder:text-black/25 focus:border-black/35";

function Field({label,children,required=false}:{label:string;children:React.ReactNode;required?:boolean}){return <label className="block"><span className="text-[9px] uppercase tracking-[.15em] text-black/38">{label}{required?<span className="ml-1 text-[#b58a37]">*</span>:null}</span><span className="mt-2 block">{children}</span></label>}
function ErrorLine({children}:{children:React.ReactNode}){return <p className="mt-2 flex items-center gap-2 text-xs text-[#8a4033]"><AlertCircle size={13}/>{children}</p>}
function Success(){return <motion.div initial={{opacity:0,y:16}} animate={{opacity:1,y:0}} className="rounded-[28px] border border-black/10 bg-[#e9e4da] p-7 md:p-10"><div className="flex h-12 w-12 items-center justify-center rounded-full bg-[#111214] text-white"><Check/></div><p className="mt-9 text-[9px] uppercase tracking-[.16em] text-black/35">Submission received</p><h3 className="mt-3 text-[clamp(2.1rem,4vw,4rem)] leading-none tracking-[-.05em]">The next step is human.</h3><p className="mt-4 max-w-xl text-sm leading-6 text-black/52">The form has passed the web-layer validation. Connect the production email/CRM provider before public launch.</p></motion.div>}

export default function MirorContactExperience(){const reduced=useReducedMotion();const [model,setModel]=useState<Model>(initial);const [state,setState]=useState<FormState>("idle");const [error,setError]=useState("");const [errors,setErrors]=useState<Record<string,string>>({});const update=<K extends keyof Model>(k:K,v:Model[K])=>{setModel((m)=>({...m,[k]:v}));setErrors((e)=>({...e,[k]:""}));};const ready=useMemo(()=>Boolean(model.name.trim()&&/^\S+@\S+\.\S+$/.test(model.email)&&model.message.trim().length>=20&&model.consent&&!model.website.trim()),[model]);function validate(){const e:Record<string,string>={};if(model.name.trim().length<2)e.name="Provide your name.";if(!/^\S+@\S+\.\S+$/.test(model.email.trim()))e.email="Enter a valid email.";if(model.message.trim().length<20)e.message="Give us at least a short project brief.";if(!model.consent)e.consent="Please confirm the response permission.";if(model.website.trim())e.website="Spam field triggered.";setErrors(e);return !Object.keys(e).length;}async function submit(event:React.FormEvent){event.preventDefault();setError("");if(!validate())return;setState("submitting");try{const body=new FormData();Object.entries(model).forEach(([k,v])=>body.set(k,String(v)));const response=await fetch("/api/enquiries",{method:"POST",body});if(!response.ok)throw new Error("Enquiry endpoint rejected the request.");setState("success");}catch(e){setState("error");setError(e instanceof Error?e.message:"Unable to submit enquiry.");}}if(state==="success")return <Success/>;return <div className="grid gap-8 lg:grid-cols-[1.25fr_.75fr]"><form onSubmit={submit} noValidate className="rounded-[28px] border border-black/10 bg-[#e9e4da] p-6 md:p-9"><div className="grid gap-6 md:grid-cols-2"><Field label="Name" required><input value={model.name} onChange={(e)=>update("name",e.target.value)} className={field} autoComplete="name" placeholder="Your name"/>{errors.name?<ErrorLine>{errors.name}</ErrorLine>:null}</Field><Field label="Company"><input value={model.company} onChange={(e)=>update("company",e.target.value)} className={field} autoComplete="organization" placeholder="Company name"/></Field><Field label="Email" required><input value={model.email} onChange={(e)=>update("email",e.target.value)} className={field} autoComplete="email" inputMode="email" placeholder="name@company.com"/>{errors.email?<ErrorLine>{errors.email}</ErrorLine>:null}</Field><Field label="Phone"><input value={model.phone} onChange={(e)=>update("phone",e.target.value)} className={field} autoComplete="tel" inputMode="tel" placeholder="+91"/></Field><Field label="Project type"><select value={model.type} onChange={(e)=>update("type",e.target.value)} className={field+" appearance-none"}><option value="">Select a scope</option>{types.map((t)=><option key={t} value={t}>{t}</option>)}</select></Field><Field label="Project location"><input value={model.location} onChange={(e)=>update("location",e.target.value)} className={field} placeholder="City / state"/></Field><Field label="Project brief" required><textarea value={model.message} onChange={(e)=>update("message",e.target.value)} className={field+" min-h-[160px] resize-y md:col-span-2"} placeholder="Tell us about the package, site, scope or requirement."/>{errors.message?<ErrorLine>{errors.message}</ErrorLine>:null}</Field></div><label className="mt-6 flex items-start gap-3 border-t border-black/10 pt-6"><input type="checkbox" checked={model.consent} onChange={(e)=>update("consent",e.target.checked)} className="mt-1 h-4 w-4"/><span className="text-xs leading-5 text-black/48">I agree that Miror may use the information supplied to respond to this enquiry.</span></label>{errors.consent?<ErrorLine>{errors.consent}</ErrorLine>:null}<input value={model.website} onChange={(e)=>update("website",e.target.value)} aria-hidden tabIndex={-1} className="absolute -left-[10000px] h-px w-px opacity-0" autoComplete="off"/><div className="mt-7 flex flex-col gap-4 border-t border-black/10 pt-6 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-2 text-[9px] uppercase tracking-[.13em] text-black/32"><ShieldCheck size={14}/> Server validation ready</div><button disabled={!ready||state==="submitting"} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-full bg-[#111214] px-5 py-3 text-xs text-[#f4f1ea] disabled:opacity-30">{state==="submitting"?<><Loader2 size={15} className="animate-spin"/> Sending</>:<><Send size={15}/> Send enquiry</>}</button></div>{state==="error"?<p className="mt-4 rounded-xl bg-[#8a4033]/10 px-4 py-3 text-xs text-[#7f3b31]">{error}</p>:null}</form><aside className="rounded-[28px] bg-[#111214] p-6 text-[#f4f1ea] md:p-9"><p className="text-[9px] uppercase tracking-[.16em] text-white/35">Direct channels</p><div className="mt-10 space-y-8"><div><p className="flex items-center gap-2 text-[9px] uppercase tracking-[.14em] text-white/35"><MapPin size={14}/> Registered office</p><p className="mt-3 text-sm leading-6 text-white/65">{contact.office}</p></div><div className="border-t border-white/10 pt-8"><p className="flex items-center gap-2 text-[9px] uppercase tracking-[.14em] text-white/35"><Mail size={14}/> Email</p><a href={`mailto:${contact.email}`} className="mt-3 inline-flex items-center gap-2 text-sm text-white/70 hover:text-white">{contact.email}<ArrowUpRight size={14}/></a></div><div className="border-t border-white/10 pt-8"><p className="text-[9px] uppercase tracking-[.14em] text-white/35">Response target</p><p className="mt-3 text-sm text-white/65">{contact.responseTarget}, subject to production connector availability.</p></div></div></aside></div>}

